```cpp
#include <iostream>
#include <vector>
using namespace std;
int main() {
    int cases;
    cin >> cases;
    while (cases--) {
        int relatives;
        cin >> relatives;
        vector<int> addresses(relatives);
        for (int i = 0; i < relatives; ++i)
            cin >> addresses[i];
        long long totalDistance = 0;
        for (int i = 0; i < relatives - 1; ++i) {
            totalDistance += abs(addresses[i] - addresses[i + 1]);
        }
        cout << totalDistance << endl;
    }
}
```

